css:
html{scroll-behavior:smooth}
body{margin:0;background:#fff;color:#17202a;font-family:var(--page-sans),sans-serif;font-size:16.5px;line-height:1.75;word-break:keep-all;overflow-wrap:break-word;-webkit-font-smoothing:antialiased}
*{box-sizing:border-box}
.num{font-family:var(--page-mono),monospace;font-feature-settings:'tnum';letter-spacing:-.02em}
a{color:inherit}
a:focus-visible,summary:focus-visible{outline:3px solid #2563eb;outline-offset:3px;border-radius:4px}
.top{position:sticky;top:0;z-index:5;background:rgba(255,255,255,.94);backdrop-filter:blur(8px);border-bottom:1px solid #dde3ea}
.bar{max-width:880px;margin:0 auto;padding:12px 20px;display:flex;align-items:center;justify-content:space-between;gap:16px}
.who{font-weight:800;text-decoration:none;font-size:1.05rem}
.bar nav{display:flex;gap:4px;overflow-x:auto}
.bar nav a{padding:6px 10px;border-radius:6px;text-decoration:none;font-size:.9rem;color:#526070;white-space:nowrap}
.bar nav a:hover{background:#eff4ff;color:#2563eb}
.col{max-width:680px;margin:0 auto;padding:0 20px}
.fig{max-width:880px;margin:44px auto;padding:0 20px}
.hero{padding:72px 0 24px}
.role{margin:0 0 18px;color:#2563eb;font-weight:700}
h1{margin:0 0 24px;font-size:clamp(2.1rem,6vw,3.4rem);line-height:1.2;font-weight:800;letter-spacing:-.035em}
.lead{margin:0;font-size:1.1rem;color:#33414f}
.ledger{margin:0;border-top:3px solid #17202a}
.row{display:flex;align-items:baseline;justify-content:space-between;gap:20px;padding:14px 0;border-bottom:1px solid #dde3ea}
.row dt{font-weight:600;color:#33414f}
.row dd{margin:0;display:flex;align-items:baseline;gap:14px;text-align:right;flex-wrap:wrap;justify-content:flex-end}
.row .num{font-size:1.4rem;font-weight:700}
.row .ctx{color:#526070;font-size:.9rem}
.row.main{padding:28px 0;background:#eff4ff;margin:0 -16px;padding-left:16px;padding-right:16px;border-bottom-color:#2563eb}
.row.main dt{font-size:1.15rem;color:#17202a}
.row.main .big{font-size:clamp(3rem,10vw,5.2rem);line-height:1;color:#2563eb;font-weight:800}
.sec{padding:72px 0 8px}
h2{margin:0 0 14px;font-size:clamp(1.5rem,4vw,1.9rem);line-height:1.35;font-weight:750;letter-spacing:-.025em}
.when{margin:0 0 14px;color:#2563eb;font-size:.95rem;font-weight:600}
.claim{font-size:1.1rem;font-weight:600;color:#17202a}
.focus{padding:14px 16px;background:#eff4ff;border-radius:8px;color:#33414f}
.focus span{font-weight:700;margin-right:12px;color:#2563eb}
.chart{margin:0;padding:24px;border:1px solid #dde3ea;border-radius:12px;max-width:680px;margin-left:auto;margin-right:auto}
.chart figcaption{font-weight:700;margin-bottom:14px}
.chart figcaption.second{margin-top:28px}
.cmp{display:grid;grid-template-columns:96px 1fr 84px;gap:14px;align-items:center;margin:10px 0}
.nm{color:#526070;font-size:.95rem}
.cmp b{text-align:right;font-size:1.05rem}
.track{display:block;height:20px;background:#f1f4f8;border-radius:4px;overflow:hidden}
.fill{display:block;height:100%;background:#2563eb;transform-origin:left;animation:grow 1s .2s cubic-bezier(.2,.7,.2,1) both}
.fill.soft{background:#aebbd0}
@keyframes grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.tt{display:block;width:100%;height:auto}
.tt .b rect{fill:#fff;stroke:#17202a;stroke-width:1.5}
.tt .b.hi rect{fill:#2563eb;stroke:#2563eb}
.tt .t1{font:700 17px var(--page-sans),sans-serif;fill:#17202a}
.tt .t2{font:400 14px var(--page-sans),sans-serif;fill:#526070}
.tt .hi .t1{fill:#fff}
.tt .c{text-anchor:middle}
.tt .ln{fill:none;stroke:#17202a;stroke-width:1.5}
.tt .ar{fill:#17202a}
.story{margin:0}
.story>div{padding:4px 0 4px 20px;border-left:3px solid #dde3ea;margin-bottom:24px}
.story>div:last-child{border-left-color:#2563eb}
.story dt{font-weight:800;margin-bottom:2px}
.story dd{margin:0;color:#33414f}
.story dd .num{color:#17202a;font-weight:700;font-size:.95em}
.flow{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:0;counter-reset:s}
.flow li{position:relative;padding:18px 16px;border:1px solid #dde3ea;margin-left:-1px;display:flex;flex-direction:column;gap:2px;counter-increment:s}
.flow li:before{content:counter(s);font-family:var(--page-mono),monospace;font-size:.8rem;color:#2563eb;font-weight:700}
.flow li b{font-size:1.02rem}
.flow li span{font-size:.9rem;color:#526070}
.flow li.gate{background:#2563eb;border-color:#2563eb;color:#fff}
.flow li.gate:before,.flow li.gate span{color:#dbe6ff}
.career{list-style:none;margin:32px 0 0;padding:0}
.career li{display:grid;grid-template-columns:150px 1fr;gap:16px;padding:16px 0;border-top:1px solid #dde3ea}
.career li>span{color:#2563eb;font-size:.9rem;font-weight:600;padding-top:3px}
.career p{margin:2px 0 0;color:#33414f;font-size:.95rem}
.ev{margin-top:20px;border-top:3px solid #17202a}
.ev details{border-bottom:1px solid #dde3ea}
.ev summary{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 4px;cursor:pointer;list-style:none;font-weight:600}
.ev summary::-webkit-details-marker{display:none}
.ev summary:hover{background:#eff4ff}
.ev summary em{font-style:normal;font-size:.85rem;color:#2563eb;background:#eff4ff;padding:2px 10px;border-radius:99px;white-space:nowrap;font-weight:600}
.ev details[open] summary{color:#2563eb}
.ev details p{margin:0;padding:0 4px 18px;color:#33414f;animation:open .25s ease both}
@keyframes open{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}
.foot{margin-top:80px;padding:32px 0 48px;border-top:1px solid #dde3ea;color:#526070;font-size:.9rem}
@media (max-width:720px){
.bar{flex-direction:column;align-items:flex-start;gap:4px}
.hero{padding-top:44px}
.sec{padding-top:56px}
.row{flex-direction:column;gap:4px}
.row dd{justify-content:flex-start;text-align:left}
.row.main{margin:0 -4px}
.cmp{grid-template-columns:64px 1fr 72px;gap:10px}
.chart{padding:18px 14px}
.flow{grid-template-columns:1fr}
.flow li{margin-left:0;margin-top:-1px}
.career li{grid-template-columns:1fr;gap:2px}
}
@media (prefers-reduced-motion:reduce){.fill,.ev details p{animation:none}html{scroll-behavior:auto}}
